mapper.select:
SELECT 'LEVEL' AS categoryType, warning_level AS category, COUNT(*) AS count, ROUND(COUNT(*) * 100.0 / NULLIF((SELECT COUNT(*) FROM gc_warning_alert_list_table WHERE deleted = b'0'), 0), 2) AS percentage FROM gc_warning_alert_list_table WHERE deleted = b'0' GROUP BY warning_level
UNION ALL
SELECT 'STATUS' AS categoryType, warning_status AS category, COUNT(*) AS count, ROUND(COUNT(*) * 100.0 / NULLIF((SELECT COUNT(*) FROM gc_warning_alert_list_table WHERE deleted = b'0'), 0), 2) AS percentage FROM gc_warning_alert_list_table WHERE deleted = b'0' GROUP BY warning_status ORDER BY categoryType, CASE WHEN categoryType = 'LEVEL' THEN CASE category WHEN 'emergency' THEN 1 WHEN 'important' THEN 2 WHEN 'general' THEN 3 WHEN 'secondary' THEN 4 ELSE 99 END ELSE 0 END, CASE WHEN categoryType = 'STATUS' THEN count ELSE 0 END DESC;
